import json
import pathlib

from pyeng.components.system.input import schemas


def generate_from_dir(json_dir: str, output_path: str) -> None:
  dir_path = pathlib.Path(json_dir)
  json_files = list(dir_path.glob('*.json'))

  lines = [
    '###',
    '### AUTOMATICALLY GENERATED BY INPUT CODEGEN - DO NOT EDIT MANUALLY',
    '###',
    '',
    'from pyeng.components.system.input.actions import ButtonAction',
    'from pyeng.components.system.input.actions import InputActionMap',
    'from pyeng.components.system.input.actions import Vector1Action',
    'from pyeng.components.system.input.actions import Vector2Action',
    'from pyeng.components.system.input.input import InputState',
    'from pyeng.components.system.system_manager import system_manager',
    '',
    '',
  ]

  map_class_names = []

  for file_path in json_files:
    map_name = file_path.stem.lower()
    class_name = f'_{map_name.capitalize()}Map'
    map_class_names.append((map_name, class_name))

    with open(file_path) as f:
      raw_data = json.load(f)

    action_map = schemas.ActionMapConfig(
      map_name=map_name,
      actions=[schemas.ActionConfig.model_validate(act) for act in raw_data],
    )

    lines.extend(
      [
        f'class {class_name}(InputActionMap):',
        '  def __init__(self, get_states_func):',
        '    super().__init__()',
      ]
    )

    for action in action_map.actions:
      act_name = action.name.lower().replace(' ', '_')

      if action.action_type == schemas.ActionType.BUTTON and action.button:
        lines.append(
          f'    self.{act_name} = ButtonAction(self, get_states_func({action.button}))'
        )

      elif action.action_type == schemas.ActionType.VECTOR1 and action.vector1:
        pos = action.vector1.positive
        neg = action.vector1.negative
        lines.append(
          f'    self.{act_name} = Vector1Action(self, get_states_func({pos}), get_states_func({neg}))'
        )

      elif action.action_type == schemas.ActionType.VECTOR2 and action.vector2:
        up = action.vector2.up
        down = action.vector2.down
        left = action.vector2.left
        right = action.vector2.right
        lines.extend(
          [
            f'    self.{act_name} = Vector2Action(',
            '      self,',
            f'      get_states_func({up}),',
            f'      get_states_func({down}),',
            f'      get_states_func({left}),',
            f'      get_states_func({right}),',
            '    )',
          ]
        )

    lines.append('')

  lines.extend(
    [
      'class InputActions:',
      '  __instance = None',
      '',
      '  def __new__(cls):',
      '    if cls.__instance is None:',
      '      cls.__instance = super().__new__(cls)',
      '      cls.__instance._initialized = False',
      '    return cls.__instance',
      '',
      '',
      '  def __init__(self):',
      "    if getattr(self, '_initialized', False):",
      '      return',
      '    self._initialized = True',
      '    self._input_sys = system_manager.get_input()',
    ]
  )

  for map_name, class_name in map_class_names:
    lines.append(f'    self.{map_name} = {class_name}(self._get_states)')

  lines.extend(
    [
      '',
      '',
      '  def _get_states(self, input_ids: list[int]) -> list[InputState]:',
      '    return [self._input_sys.get_or_create_state(k_id) for k_id in input_ids]',
    ]
  )

  with open(output_path, 'w') as f:
    f.write('\n'.join(lines))


if __name__ == '__main__':
  generate_from_dir('./data/config/input_maps', 'data/config/input_actions.py')
